/**
 * Utility class for importing files safely.
 */
public class ImportingUtilities {

    // other methods

    /**
     * Allocates a new {@link File} inside {@code dir} with a sanitized {@code name}.
     *
     * <p>This method protects against directory‑traversal attacks by ensuring that the
     * resolved file path stays within {@code dir}. It also guarantees that the file
     * name does not contain any absolute path components or path separators.</p>
     *
     * @param dir  the base directory where the file should be created
     * @param name the desired file name (may come from an untrusted source)
     * @return a {@link File} instance pointing to a unique file inside {@code dir}
     * @throws IOException          if an I/O error occurs while resolving paths
     * @throws SecurityException    if the resolved path is outside {@code dir}
     * @throws IllegalArgumentException if {@code dir} or {@code name} is null or empty
     */
    static public File allocateFile(File dir, String name) throws IOException {
        if (dir == null || name == null) {
            throw new IllegalArgumentException("Directory and name must not be null");
        }

        // Strip query parameters
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Reject empty names
        if (name.isEmpty()) {
            throw new IllegalArgumentException("Name must not be empty");
        }

        // Reject absolute paths or paths containing separators
        Path rawNamePath = Paths.get(name);
        if (rawNamePath.isAbsolute() || rawNamePath.getNameCount() > 1) {
            throw new SecurityException("Invalid file name: " + name);
        }

        // Resolve the target path and normalize it
        Path dirPath = dir.toPath().toRealPath(); // canonical path of the base directory
        Path targetPath = dirPath.resolve(rawNamePath).normalize();

        // Ensure the target remains inside the base directory
        if (!targetPath.startsWith(dirPath)) {
            throw new SecurityException("Attempted directory traversal: " + name);
        }

        // Handle duplicate names by appending "-n" before the extension
        String originalName = targetPath.getFileName().toString();
        String prefix;
        String suffix;
        int dotIndex = originalName.lastIndexOf('.');
        if (dotIndex < 0) {
            prefix = originalName;
            suffix = "";
        } else {
            prefix = originalName.substring(0, dotIndex);
            suffix = originalName.substring(dotIndex);
        }

        int index = 2;
        Path candidate = targetPath;
        while (Files.exists(candidate)) {
            String newName = prefix + "-" + index++ + suffix;
            candidate = dirPath.resolve(newName);
        }

        // Create parent directories if necessary
        Files.createDirectories(candidate.getParent());

        return candidate.toFile();
    }

