            throw new ArchiverException("Entry name is null or empty");
        }

        // Resolve the target file
        final File f = FileUtils.resolveFile(dir, entryName);

        // Security check – prevent Zip‑Slip attacks
        final File canonicalDir = dir.getCanonicalFile();
        final File canonicalF = f.getCanonicalFile();
        final String canonicalDirPath = canonicalDir.getPath();
        final String canonicalFPath = canonicalF.getPath();

        if (!canonicalFPath.equals(canonicalDirPath)
                && !canonicalFPath.startsWith(canonicalDirPath + File.separator)) {
            throw new ArchiverException(
                    "Entry '" + entryName + "' resolves to a location outside the target directory");
        }

        try {
            if (!isOverwrite() && f.exists() && (f.lastModified() >= entryDate.getTime())) {
                return;
            }

            final File dirF = f.getParentFile();
            if (dirF != null) {
                dirF.mkdirs();
            }

            if (!StringUtils.isEmpty(symlinkDestination)) {
                SymlinkUtils.createSymbolicLink(f, new File(symlinkDestination));
            } else if (isDirectory) {
                f.mkdirs();
            } else {
