        final int total = out.length;

        while (position < total) {
            int n = in.read();
            if (n == -1) {
                throw new EOFException("Unexpected end of stream while reading packet header");
            }

            // According to the Rgbe specification, a packet length of 0 is invalid.
            if (n == 0) {
                throw new IOException("Invalid packet length 0 encountered during decompression");
            }

