                int value = in.read();
                if (value == -1) {
                    throw new EOFException("Unexpected end of stream while reading run value");
                }
                int count = n & 0x7F; // lower 7 bits give the repeat count
                if (position + count > total) {
                    throw new IOException("Compressed data exceeds output buffer size");
                }
                for (int i = 0; i < count; i++) {
                    out[position++] = (byte) value;
                }
            } else { // Raw packet
                int count = n; // number of literal bytes to copy
                if (position + count > total) {
                    throw new IOException("Compressed data exceeds output buffer size");
                }
                for (int i = 0; i < count; i++) {
                    int b = in.read();
                    if (b == -1) {
                        throw new EOFException("Unexpected end of stream while reading raw data");
                    }
                    out[position++] = (byte) b;
                }
            }
        }
    }

