import java.io.InputStream;
import java.io.StringReader;
import java.io.Reader;
import java.io.IOException;
import java.io.Closeable;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.XMLConstants;
import org.w3c.dom.Document;
import org.xml.sax.InputSource;
import org.apache.camel.Exchange;
import org.apache.camel.Expression;
import org.apache.camel.NoTypeConversionAvailableException;
import org.apache.camel.Predicate;
import org.apache.camel.WrappedFile;
import org.apache.camel.component.bean.BeanInvocation;
import org.apache.camel.spi.NamespaceAware;
import org.apache.camel.support.ServiceSupport;

/**
 * A thread‑safe XPath expression builder that safely parses XML documents.
 *
 * <p>The original implementation was vulnerable to XML External Entity (XXE)
 * attacks because it relied on Camel's default type converters which do not
 * disable external entity resolution.  The patched version explicitly creates
 * a {@link DocumentBuilderFactory} with secure features enabled and parses
 * XML input only through that factory.</p>
 */
public class XPathBuilder extends ServiceSupport implements Expression, Predicate, NamespaceAware {

    private final ThreadLocal<Exchange> exchange = new ThreadLocal<Exchange>();
    private volatile Class<?> documentType = Document.class;

    // -------------------------------------------------------------------------
    // Public API
    // -------------------------------------------------------------------------

    @Override
    protected Object doGetDocument(Exchange exchange, Object body) throws Exception {
        if (body == null) {
            return null;
        }

        // If a specific document type is requested, attempt to convert it.
        Class<?> type = getDocumentType();
        if (type != null && !Document.class.equals(type)) {
            Object answer = null;
            Exception cause = null;
            try {
                answer = exchange.getContext().getTypeConverter()
                                 .convertTo(type, exchange, body);
            } catch (Exception e) {
                cause = e;
            }
            if (answer != null) {
                return answer;
            }
            if (cause != null) {
                throw cause;
            }
            throw new NoTypeConversionAvailableException(body, type);
        }

        // From here on we only care about Document.class
        if (!Document.class.equals(type)) {
            // No conversion requested – return the original body.
            return body;
        }

        Document answer = null;
        Exception cause = null;

        try {
            if (body instanceof WrappedFile) {
                InputStream is = exchange.getContext().getTypeConverter()
                                         .convertTo(InputStream.class, exchange, body);
                answer = parseSecureFromInputStream(is);
            } else if (body instanceof BeanInvocation) {
                BeanInvocation bi = exchange.getContext().getTypeConverter()
                                            .convertTo(BeanInvocation.class, exchange, body);
                if (bi.getArgs() != null && bi.getArgs().length == 1 && bi.getArgs()[0] == null) {
                    answer = null;
                }
            } else if (body instanceof String) {
                answer = parseSecureFromReader(new StringReader((String) body));
            } else if (body instanceof InputStream) {
                answer = parseSecureFromInputStream((InputStream) body);
            } else if (body instanceof Reader) {
                answer = parseSecureFromReader((Reader) body);
            } else {
                // Fallback to Camel's type converter for unknown types
                answer = exchange.getContext().getTypeConverter()
                                 .convertTo(Document.class, exchange, body);
            }
        } catch (Exception e) {
            cause = e;
        }

        if (answer == null) {
            if (cause != null) {
                throw cause;
            }
            throw new NoTypeConversionAvailableException(body, Document.class);
        }

        return answer;
    }

    public Class<?> getDocumentType() {
        return documentType;
    }

    // -------------------------------------------------------------------------
    // Secure XML parsing helpers
    // -------------------------------------------------------------------------

    /**
     * Parses XML from an {@link InputStream} using a {@link DocumentBuilderFactory}
     * that has all features required to mitigate XXE attacks.
     *
     * @param is the input stream containing XML
     * @return a parsed {@link Document}
     * @throws Exception if parsing fails
     */
    private Document parseSecureFromInputStream(InputStream is) throws Exception {
        try {
            DocumentBuilderFactory dbf = createSecureFactory();
            DocumentBuilder db = dbf.newDocumentBuilder();
            return db.parse(is);
        } finally {
            closeQuietly(is);
        }
    }

    /**
     * Parses XML from a {@link Reader} using a {@link DocumentBuilderFactory}
     * that has all features required to mitigate XXE attacks.
     *
     * @param reader the reader containing XML
     * @return a parsed {@link Document}
     * @throws Exception if parsing fails
     */
    private Document parseSecureFromReader(Reader reader) throws Exception {
        try {
            DocumentBuilderFactory dbf = createSecureFactory();
            DocumentBuilder db = dbf.newDocumentBuilder();
            return db.parse(new InputSource(reader));
        } finally {
            closeQuietly(reader);
        }
    }

    /**
     * Creates a {@link DocumentBuilderFactory} with security features enabled.
     *
     * @return a secure {@link DocumentBuilderFactory}
     * @throws Exception if the factory cannot be created
     */
    private DocumentBuilderFactory createSecureFactory() throws Exception {
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
        dbf.setNamespaceAware(true);
        dbf.setValidating(false);
        dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        // Disallow DOCTYPE declarations
        dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        // Disable external entities
        dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
        dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        dbf.setXIncludeAware(false);
        dbf.setExpandEntityReferences(false);
        return dbf;
    }

    /**
     * Closes a {@link Closeable} quietly.
     *
     * @param c the closeable resource
     */
    private void closeQuietly(Closeable c) {
        if (c != null) {
            try {
                c.close();
            } catch (IOException ignored) {
                // ignore
            }
        }
    }
}
