     * Compare {@code fromVersion} and {@code toVersion}.
     *
     * <p>The method expects both versions to be in the form {@code "x.y.z"} where
     * {@code x}, {@code y} and {@code z} are integer values. Any deviation from
     * this format will result in an {@link IllegalArgumentException}. This
     * defensive approach prevents {@link ArrayIndexOutOfBoundsException} and
     * {@link NumberFormatException} that could otherwise lead to a denial‑of‑service
     * scenario.</p>
     *
     * @param fromVersion the initial version string
     * @param toVersion   the target version string
     * @return a negative integer if {@code fromVersion} is less than {@code toVersion},
     *         zero if they are equal, or a positive integer otherwise
     * @throws IllegalArgumentException if either argument is {@code null},
     *                                  does not contain exactly three dot‑separated
     *                                  components, or contains non‑numeric parts
     */
    public static int versionCompare(String fromVersion, String toVersion) {
        // Basic null checks
        if (fromVersion == null || toVersion == null) {
            throw new IllegalArgumentException("Version strings must not be null");
        }

        // Split into components and validate length
        String[] fromParts = fromVersion.split("\\.");
        String[] toParts = toVersion.split("\\.");

        if (fromParts.length != 3 || toParts.length != 3) {
            throw new IllegalArgumentException(
                "Version strings must have exactly three numeric components separated by '.'");
        }

        // Parse each component safely
        int fromMajor = parseComponent(fromParts[0], "major");
        int fromMinor = parseComponent(fromParts[1], "minor");
        int fromPatch = parseComponent(fromParts[2], "patch");

        int toMajor = parseComponent(toParts[0], "major");
        int toMinor = parseComponent(toParts[1], "minor");
        int toPatch = parseComponent(toParts[2], "patch");

        // Perform comparison using Integer.compare for clarity
        int cmp = Integer.compare(fromMajor, toMajor);
        if (cmp != 0) {
            return cmp;
        }

        cmp = Integer.compare(fromMinor, toMinor);
        if (cmp != 0) {
            return cmp;
        }

        return Integer.compare(fromPatch, toPatch);
    }

    /**
     * Parses a single numeric component of a version string.
     *
     * @param part the string representation of the component
     * @param name the semantic name of the component (used in exception messages)
     * @return the parsed integer value
     * @throws IllegalArgumentException if the component cannot be parsed as an integer
     */
    private static int parseComponent(String part, String name) {
        try {
            return Integer.parseInt(part);
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException(
                "Invalid " + name + " component in version string: '" + part + "'", e);
        }
    }

    // other methods

}
