import javax.xml.parsers.SAXParser;
import javax.xml.parsers.SAXParserFactory;
import javax.xml.transform.sax.SAXSource;
import javax.xml.transform.stream.StreamSource;
import javax.xml.XMLConstants;
import org.xml.sax.InputSource;
import org.xml.sax.SAXException;
import org.xml.sax.XMLReader;
import org.xml.sax.SAXNotRecognizedException;
import org.xml.sax.SAXNotSupportedException;
import org.apache.camel.Converter;
import org.apache.camel.Exchange;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@Converter
public class XmlConverter {

    private static final Logger LOG = LoggerFactory.getLogger(XmlConverter.class);

    // other methods

    @Converter
    public SAXSource toSAXSourceFromStream(StreamSource source, Exchange exchange) throws SAXException {
        InputSource inputSource;
        if (source.getReader() != null) {
            inputSource = new InputSource(source.getReader());
        } else {
            inputSource = new InputSource(source.getInputStream());
        }
        inputSource.setSystemId(source.getSystemId());
        inputSource.setPublicId(source.getPublicId());

        XMLReader xmlReader = null;
        SAXParserFactory sfactory = null;

        try {
            // Prefer a factory supplied by the exchange, otherwise create a new one
            if (exchange != null) {
                sfactory = exchange.getProperty(Exchange.SAXPARSER_FACTORY, SAXParserFactory.class);
            }
            if (sfactory == null) {
                sfactory = SAXParserFactory.newInstance();
            }

            // Enable secure processing on the factory
            try {
                sfactory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
            } catch (Exception e) {
                LOG.warn("SAXParserFactory does not support FEATURE_SECURE_PROCESSING: {}", e.toString());
            }

            // Disable loading of external DTDs and grammars
            try {
                sfactory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
            } catch (Exception e) {
                LOG.debug("Failed to disable load-external-dtd: {}", e.toString());
            }
            try {
                sfactory.setFeature("http://apache.org/xml/features/nonvalidating/load-dtd-grammar", false);
            } catch (Exception e) {
                LOG.debug("Failed to disable load-dtd-grammar: {}", e.toString());
            }

            sfactory.setNamespaceAware(true);

            SAXParser parser = sfactory.newSAXParser();
            xmlReader = parser.getXMLReader();

            // Disable external entity resolution on the XMLReader
            try {
                xmlReader.setFeature("http://xml.org/sax/features/external-general-entities", false);
            } catch (SAXNotRecognizedException | SAXNotSupportedException e) {
                LOG.debug("XMLReader does not support disabling external-general-entities: {}", e.toString());
            }
            try {
                xmlReader.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
            } catch (SAXNotRecognizedException | SAXNotSupportedException e) {
                LOG.debug("XMLReader does not support disabling external-parameter-entities: {}", e.toString());
            }

            // Disallow DOCTYPE declarations entirely
            try {
                xmlReader.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            } catch (SAXNotRecognizedException | SAXNotSupportedException e) {
                LOG.debug("XMLReader does not support disallow-doctype-decl: {}", e.toString());
            }

        } catch (Exception ex) {
            LOG.warn("Cannot create the SAXParser XMLReader, due to {}", ex.toString());
        }

        if (xmlReader == null) {
            throw new IllegalStateException("Failed to instantiate a secure XMLReader");
        }

        return new SAXSource(xmlReader, inputSource);
    }

    // other methods

}
